sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=2;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader amzt_cells;
float4 amzSample_cells(float2 uv) { return float4(amzt_cells.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/8.0)); }
uniform shader amzt_stat;
float4 amzSample_stat(float2 uv) { return float4(amzt_stat.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/64.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_cells(uv);if(tex==2) return amzSample_stat(uv);return float4(0.0); }
uniform float amzp_safeRender;
uniform float amzp_boxOn;
uniform float amzp_linkOn;
uniform float amzp_curveOn;
uniform float amzp_textOn;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_seed;
uniform float amzp_track;
uniform float amzp_threshold;
uniform float amzp_cellSize;
uniform float amzp_density;
uniform float amzp_rate;
uniform float amzp_boxStyle;
uniform float2 amzp_boxSz;
uniform float amzp_sizeVar;
uniform float amzp_lineWidth;
layout(color) uniform half4 amzp_boxColor;
uniform float amzp_fillMode;
uniform float amzp_fillOpacity;
uniform float amzp_linkDist;
uniform float amzp_linkProb;
layout(color) uniform half4 amzp_lineColor;
uniform float amzp_dashed;
uniform float amzp_curveProb;
uniform float amzp_curveBend;
uniform float amzp_curveDash;
uniform float amzp_arrowCount;
uniform float amzp_arrowSize;
layout(color) uniform half4 amzp_curveColor;
uniform float amzp_labelMode;
uniform float amzp_textStyle;
uniform float amzp_textSize;
layout(color) uniform half4 amzp_textColor;
uniform float amzp_composite;
uniform float amzp_opacity;
uniform float amzp_overdrawOn;
    float hs;
    float h2(float2 q, float k) { return fract(sin(dot(q, float2(127.1, 311.7)) + k * 74.7 + hs * 0.173) * 43758.5453); }
    float2 scr() { return (screen.zw/1.0); }
    float pxs() { return (screen.zw/1.0).x / max(screen.zw.x, 1.0); }
    float cellPx() { return max(max(amzp_cellSize, 100.0) * pxs(), max(scr().x / max((screen.zw/8.0).x, 1.0), scr().y / max((screen.zw/8.0).y, 1.0))); }
    float score(float4 c, float mean) {
        float l = dot(c.rgb, float3(0.299, 0.587, 0.114));
        if (int(amzp_track) == 1) return (1.0 - (c.a > 0.0001 ? l / c.a : 1.0)) * c.a;
        if (int(amzp_track) == 2) return clamp(abs(l - mean) * 3.0, 0.0, 1.0);
        return l;
    }
    float glyph(float g) {
        if (g < 0.5) return 31599.0;
        if (g < 1.5) return 11415.0;
        if (g < 2.5) return 29671.0;
        if (g < 3.5) return 29647.0;
        if (g < 4.5) return 23497.0;
        if (g < 5.5) return 31183.0;
        if (g < 6.5) return 31215.0;
        if (g < 7.5) return 29257.0;
        if (g < 8.5) return 31727.0;
        if (g < 9.5) return 31695.0;
        if (g < 10.5) return 20.0;
        if (g < 11.5) return 2.0;
        if (g < 12.5) return 24445.0;
        if (g < 13.5) return 341.0;
        if (g < 14.5) return 2910.0;
        if (g < 15.5) return 3640.0;
        return 0.0;
    }
    float bitAt(float code, float row, float col) {
        float b = row * 3.0 + col;
        return mod(floor(code / pow(2.0, 14.0 - b)), 2.0);
    }
    float nDigits(float v) { return v < 10.0 ? 1.0 : (v < 100.0 ? 2.0 : (v < 1000.0 ? 3.0 : (v < 10000.0 ? 4.0 : 5.0))); }
    float digitOf(float v, float nd, float k) { return mod(floor(v / pow(10.0, nd - 1.0 - k)), 10.0); }
    float labelChar(float k, float id, float2 xy, float sc) {
        if (int(amzp_labelMode) == 4) {
            float nx = nDigits(xy.x), ny = nDigits(xy.y);
            if (k < 0.5) return 13.0;
            if (k < 1.5) return 15.0;
            if (k < 2.0 + nx) return digitOf(xy.x, nx, k - 2.0);
            if (k < 2.5 + nx) return 16.0;
            if (k < 3.5 + nx) return 14.0;
            if (k < 4.5 + nx) return 15.0;
            return k - nx - 5.0 < ny ? digitOf(xy.y, ny, k - nx - 5.0) : -1.0;
        }
        if (int(amzp_labelMode) == 1) {
            if (k < 0.5) return 12.0;
            float nd = nDigits(id);
            return k - 1.0 < nd ? digitOf(id, nd, k - 1.0) : -1.0;
        }
        if (int(amzp_labelMode) == 2) {
            float nx = nDigits(xy.x), ny = nDigits(xy.y);
            if (k < nx) return digitOf(xy.x, nx, k);
            if (k < nx + 0.5) return 10.0;
            return k - nx - 1.0 < ny ? digitOf(xy.y, ny, k - nx - 1.0) : -1.0;
        }
        if (int(amzp_labelMode) == 3) {
            if (k < 0.5) return 0.0;
            if (k < 1.5) return 11.0;
            float v = clamp(floor(sc * 100.0), 0.0, 99.0);
            if (k < 2.5) return floor(v / 10.0);
            if (k < 3.5) return mod(v, 10.0);
        }
        return -1.0;
    }
    float labelLen(float id, float2 xy) {
        if (int(amzp_labelMode) == 1) return 1.0 + nDigits(id);
        if (int(amzp_labelMode) == 2) return nDigits(xy.x) + 1.0 + nDigits(xy.y);
        if (int(amzp_labelMode) == 3) return 4.0;
        if (int(amzp_labelMode) == 4) return nDigits(xy.x) + nDigits(xy.y) + 5.0;
        return 0.0;
    }
    float sdSeg(float2 p, float2 a, float2 b) {
        float2 pa = p - a, ba = b - a;
        float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
        return length(pa - ba * h);
    }
    float sdArc(float2 p, float2 c, float r, float mid, float hs) {
        float2 q = p - c;
        float m = radians(mid), h = radians(hs);
        float d = mod(abs(atan(q.y, q.x) - m), 6.2831853);
        d = min(d, 6.2831853 - d);
        if (d <= h) return abs(length(q) - r);
        float2 e0 = c + r * float2(cos(m + h), sin(m + h));
        float2 e1 = c + r * float2(cos(m - h), sin(m - h));
        return min(length(p - e0), length(p - e1));
    }
    float sdSix(float2 p) {
        float d = sdArc(p, float2(0.52, 0.47), 0.5, 140.0, 50.0);
        return min(d, abs(length(p - float2(0.3, 0.31)) - 0.28));
    }
    float sdGlyph(float g, float2 p) {
        if (g < 0.5) {
            float2 q = (p - float2(0.3, 0.5)) / float2(0.25, 0.47);
            return abs(length(q) - 1.0) * 0.25;
        }
        if (g < 1.5) return min(sdSeg(p, float2(0.36, 0.03), float2(0.36, 0.97)), sdSeg(p, float2(0.36, 0.97), float2(0.12, 0.8)));
        if (g < 2.5) {
            float d = sdArc(p, float2(0.3, 0.72), 0.24, 65.0, 100.0);
            d = min(d, sdSeg(p, float2(0.497, 0.582), float2(0.05, 0.05)));
            return min(d, sdSeg(p, float2(0.05, 0.05), float2(0.55, 0.05)));
        }
        if (g < 3.5) {
            float d = sdArc(p, float2(0.28, 0.745), 0.215, 32.5, 122.5);
            d = min(d, sdArc(p, float2(0.29, 0.3), 0.27, -32.5, 122.5));
            return min(d, sdSeg(p, float2(0.28, 0.53), float2(0.29, 0.57)));
        }
        if (g < 4.5) {
            float d = sdSeg(p, float2(0.43, 0.03), float2(0.43, 0.97));
            d = min(d, sdSeg(p, float2(0.43, 0.97), float2(0.03, 0.32)));
            return min(d, sdSeg(p, float2(0.03, 0.32), float2(0.58, 0.32)));
        }
        if (g < 5.5) {
            float d = sdSeg(p, float2(0.52, 0.95), float2(0.15, 0.95));
            d = min(d, sdSeg(p, float2(0.15, 0.95), float2(0.135, 0.541)));
            return min(d, sdArc(p, float2(0.29, 0.32), 0.27, -12.5, 137.5));
        }
        if (g < 6.5) return sdSix(p);
        if (g < 7.5) return min(sdSeg(p, float2(0.03, 0.95), float2(0.57, 0.95)), sdSeg(p, float2(0.57, 0.95), float2(0.2, 0.03)));
        if (g < 8.5) return min(abs(length(p - float2(0.3, 0.735)) - 0.215), abs(length(p - float2(0.3, 0.29)) - 0.265));
        if (g < 9.5) return sdSix(float2(0.6, 1.0) - p);
        if (g < 10.5) return sdSeg(p, float2(0.11, 0.05), float2(0.05, -0.12));
        if (g < 11.5) return length(p - float2(0.09, 0.05));
        if (g > 12.5) {
            if (g < 13.5) return min(sdSeg(p, float2(0.05, 0.03), float2(0.5, 0.6)), sdSeg(p, float2(0.05, 0.6), float2(0.5, 0.03)));
            if (g < 14.5) return min(sdSeg(p, float2(0.05, 0.6), float2(0.28, 0.05)), sdSeg(p, float2(0.52, 0.6), float2(0.16, -0.3)));
            if (g < 15.5) return min(sdSeg(p, float2(0.06, 0.4), float2(0.5, 0.4)), sdSeg(p, float2(0.06, 0.2), float2(0.5, 0.2)));
            return 9.0;
        }
        float d = min(sdSeg(p, float2(0.22, 0.1), float2(0.29, 0.9)), sdSeg(p, float2(0.4, 0.1), float2(0.47, 0.9)));
        d = min(d, sdSeg(p, float2(0.08, 0.34), float2(0.62, 0.34)));
        return min(d, sdSeg(p, float2(0.08, 0.66), float2(0.62, 0.66)));
    }
    float advance(float g) {
        if (g > 9.5 && g < 11.5) return 0.26;
        if (g > 0.5 && g < 1.5) return 0.52;
        if (g > 11.5 && g < 12.5) return 0.78;
        if (g > 12.5 && g < 15.5) return 0.62;
        if (g > 15.5) return 0.34;
        return 0.72;
    }
    float labelWidth(float nch) { return nch * 0.78; }
    float segD(float2 p, float2 a, float2 b, out float t) {
        float2 ab = b - a;
        t = clamp(dot(p - a, ab) / max(dot(ab, ab), 1e-4), 0.0, 1.0);
        return length(p - a - ab * t);
    }
    float3 thermal(float v) {
        return clamp(float3(1.5 * v - 0.2, 2.0 * v - 0.8, 1.0 - 2.5 * abs(v - 0.3)), 0.0, 1.0)
             + float3(0.0, 0.0, 0.25) * (1.0 - v);
    }
    float2 BP[25];
    float2 BH[25];
    float BA[25];
    float BS[25];
    float BI[25];
    void nmMain() {
        float2 S = scr();
        float G = cellPx();
        float2 nc = ceil(S / G);
        float autoK = (amzp_autop>0.5) ? floor(time * amzp_autoSpeed * 4.0) : 0.0;
        hs = amzp_seed + autoK * 3.31 + (amzp_rate > 0.0 ? floor(time * amzp_rate) * 5.17 : 0.0);
        if (amzPass == 0) {
            float2 idx = floor(amzScreenNorm() * (screen.zw/8.0));
            if (idx.x >= nc.x || idx.y >= nc.y) { amzOutput = float4(0.5, 0.5, 0.0, 1.0); return; }
            float2 o = idx * G;
            float mean = 0.0;
            if (int(amzp_track) == 2) {
                for (int j = 0; j < 4; j++) for (int i = 0; i < 4; i++) {
                    float4 c = amzTexture(0, (o + (float2(float(i), float(j)) + 0.5) / 4.0 * G) / S);
                    mean += dot(c.rgb, float3(0.299, 0.587, 0.114));
                }
                mean /= 16.0;
            }
            float mx = 0.0;
            for (int j = 0; j < 6; j++) for (int i = 0; i < 6; i++) {
                float2 q = (float2(float(i), float(j)) + 0.5) / 6.0;
                float s = score(amzTexture(0, (o + q * G) / S), mean);
                mx = max(mx, s);
            }
            float2 acc = float2(0.0);
            float ws = 0.0;
            for (int j = 0; j < 6; j++) for (int i = 0; i < 6; i++) {
                float2 q = (float2(float(i), float(j)) + 0.5) / 6.0;
                float s = score(amzTexture(0, (o + q * G) / S), mean);
                float w = max(s - 0.7 * mx, 0.0);
                w *= w;
                acc += q * w;
                ws += w;
            }
            float2 cen = ws > 0.0 ? acc / ws : float2(0.5);
            amzOutput = float4(cen, mx, 1.0);
            return;
        }
        if (amzPass == 1) {
            float mn = 1.0, mxv = 0.0;
            for (int j = 0; j < 64; j++) {
                if (float(j) >= nc.y) break;
                for (int i = 0; i < 64; i++) {
                    if (float(i) >= nc.x) break;
                    float s = amzTexture(1, (float2(float(i), float(j)) + 0.5) / (screen.zw/8.0)).b;
                    if (s > 0.004) { mn = min(mn, s); mxv = max(mxv, s); }
                }
            }
            if (mxv <= 0.0) mn = 0.0;
            amzOutput = float4(mn, mxv, 0.0, 1.0);
            return;
        }
        float2 uv = amzScreenNorm();
        float2 P = uv * S;
        float4 orig = amzTexture(0, uv);
        float2 ci = floor(P / G);
        float px = pxs();
        float4 stt = amzTexture(2, float2(0.5));
        float rng = max(stt.g - stt.r, 0.01);
        float wd = rng * 0.08;
        float te = mix(stt.r - wd, stt.g, clamp(amzp_threshold, 0.0, 1.0));
        float dn = clamp(amzp_density, 0.0, 1.0);
        float vr = clamp(amzp_sizeVar, 0.0, 1.0);
        float2 baseHalf = max(amzp_boxSz, float2(2.0)) * px * 0.5;
        for (int n = 0; n < 25; n++) {
            float fn = float(n);
            float2 idx = ci + float2(mod(fn, 5.0) - 2.0, floor(fn / 5.0) - 2.0);
            BA[n] = 0.0;
            BP[n] = float2(-1e5);
            BH[n] = float2(0.0);
            BS[n] = 0.0;
            BI[n] = 0.0;
            if (idx.x < 0.0 || idx.y < 0.0 || idx.x >= nc.x || idx.y >= nc.y) continue;
            float4 t = amzTexture(1, (idx + 0.5) / (screen.zw/8.0));
            if (t.b <= 0.004) continue;
            float sg = clamp((t.b - te) / wd, 0.0, 1.0);
            float sd = dn >= 0.999 ? 1.0 : clamp((dn - h2(idx, 1.0)) / 0.05, 0.0, 1.0);
            sg *= sd;
            if (sg <= 0.001) continue;
            float sc = (1.0 + vr * (h2(idx, 2.0) * 2.0 - 1.0) * 0.6) * (0.5 + 0.5 * sg);
            float asp = 1.0 + vr * (h2(idx, 3.0) - 0.5) * 0.4;
            BA[n] = sg;
            BP[n] = (idx + t.rg) * G;
            BH[n] = baseHalf * sc * float2(asp, 1.0 / asp);
            BS[n] = t.b;
            BI[n] = mod(idx.y * nc.x + idx.x + floor(h2(float2(0.0), 4.0) * 97.0), 1000.0);
        }
        float lw = max(amzp_lineWidth, 0.5) * px;
        float stroke = 0.0, lineA = 0.0, textA = 0.0, fill = 0.0;
        for (int n = 0; n < 25; n++) {
            if (BA[n] <= 0.001) continue;
            float2 d = abs(P - BP[n]);
            float2 hb = BH[n];
            if ((amzp_boxOn>0.5)) {
                float outer = max(d.x - hb.x, d.y - hb.y);
                float e = 1.0 - smoothstep(lw * 0.5 - 0.5, lw * 0.5 + 0.5, abs(outer));
                if (int(amzp_boxStyle) == 1) {
                    float2 cl = hb * 0.35;
                    e *= step(hb.x - cl.x, d.x) + step(hb.y - cl.y, d.y) > 1.5 ? 1.0 : (step(hb.x - cl.x, d.x) * step(abs(d.y - hb.y), lw) + step(hb.y - cl.y, d.y) * step(abs(d.x - hb.x), lw) > 0.5 ? 1.0 : 0.0);
                } else if (int(amzp_boxStyle) == 2) {
                    float cr = max(1.0 - smoothstep(lw * 0.5 - 0.5, lw * 0.5 + 0.5, d.x) * 1.0, 0.0) * step(d.y, hb.y * 0.5);
                    cr = max(cr, (1.0 - smoothstep(lw * 0.5 - 0.5, lw * 0.5 + 0.5, d.y)) * step(d.x, hb.x * 0.5));
                    e = max(e, cr);
                }
                stroke = max(stroke, e * BA[n]);
                if (outer < 0.0) fill = max(fill, BA[n]);
            }
            if ((amzp_textOn>0.5) && int(amzp_labelMode) > 0) {
                float2 xy = floor(float2(BP[n].x, S.y - BP[n].y) / px + 0.5);
                float nch = labelLen(BI[n], xy);
                if (int(amzp_textStyle) == 1) {
                    float H = max(amzp_textSize, 1.0) * px;
                    float2 lo = BP[n] + float2(-hb.x, hb.y + lw + H * 0.3);
                    float2 l = (P - lo) / H;
                    if (l.y > -0.25 && l.y < 1.15 && l.x > -0.05 && l.x < labelWidth(nch)) {
                        float xa = 0.0;
                        for (int k = 0; k < 12; k++) {
                            if (float(k) >= nch) break;
                            float g = labelChar(float(k), BI[n], xy, BS[n]);
                            float adv = advance(g);
                            if (l.x < xa + adv) {
                                float dd = sdGlyph(g, float2(l.x - xa, l.y));
                                float aa = 0.8 / H;
                                textA = max(textA, (1.0 - smoothstep(0.06 - aa, 0.06 + aa, dd)) * BA[n]);
                                break;
                            }
                            xa += adv;
                        }
                    }
                } else {
                    float u = max(amzp_textSize, 1.0) * px / 5.0;
                    float2 lo = BP[n] + float2(-hb.x, hb.y + lw + u);
                    float2 l = (P - lo) / u;
                    if (l.x >= 0.0 && l.y >= 0.0 && l.y < 5.0 && l.x < nch * 4.0) {
                        float k = floor(l.x / 4.0);
                        float cx = floor(l.x - k * 4.0);
                        float g = labelChar(k, BI[n], xy, BS[n]);
                        if (g >= 0.0 && cx < 3.0) textA = max(textA, bitAt(glyph(g), 4.0 - floor(l.y), cx) * BA[n]);
                    }
                }
            }
        }
        if ((amzp_linkOn>0.5)) {
            float ld = clamp(amzp_linkDist, 0.5, 2.5) * G;
            for (int a = 0; a < 25; a++) {
                if (BA[a] <= 0.001) continue;
                for (int b = 0; b < 25; b++) {
                    if (b <= a) continue;
                    if (BA[b] <= 0.001) continue;
                    float2 ab = BP[b] - BP[a];
                    float L = length(ab);
                    if (L > ld) continue;
                    if (h2(floor(BP[a] / G) * 31.0 + floor(BP[b] / G), 5.0) >= clamp(amzp_linkProb, 0.0, 1.0)) continue;
                    float t;
                    float dd = segD(P, BP[a], BP[b], t);
                    float e = 1.0 - smoothstep(lw * 0.35 - 0.5, lw * 0.35 + 0.5, dd);
                    if ((amzp_dashed>0.5)) e *= step(0.5, fract(t * L / (10.0 * px)));
                    lineA = max(lineA, e * min(BA[a], BA[b]));
                }
            }
        }
        float arrA = 0.0;
