        o = float4(amzp_curveColor.rgb, 1.0) * arrA * op + o * (1.0 - arrA * op);
        o = float4(amzp_boxColor.rgb, 1.0) * stroke * op + o * (1.0 - stroke * op);
        o = float4(amzp_textColor.rgb, 1.0) * textA * op + o * (1.0 - textA * op);
        amzOutput = float4(min(o.rgb, float3(o.a)), o.a);
    }
    void amzRender() {
        if ((amzp_safeRender>0.5)) { amzOutput = amzTexture(0, amzScreenNorm()); return; }
        nmMain();
        if (!(amzp_overdrawOn>0.5) && amzPass >= 2) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

