                float outer = max(d.x - hb.x, d.y - hb.y);
                float e = 1.0 - smoothstep(lw * 0.5 - 0.5, lw * 0.5 + 0.5, abs(outer));
                if (int(amzp_boxStyle) == 1) {
                    float2 cl = hb * 0.35;
                    e *= step(hb.x - cl.x, d.x) + step(hb.y - cl.y, d.y) > 1.5 ? 1.0 : (step(hb.x - cl.x, d.x) * step(abs(d.y - hb.y), lw) + step(hb.y - cl.y, d.y) * step(abs(d.x - hb.x), lw) > 0.5 ? 1.0 : 0.0);
                } else if (int(amzp_boxStyle) == 2) {
                    float cr = max(1.0 - smoothstep(lw * 0.5 - 0.5, lw * 0.5 + 0.5, d.x) * 1.0, 0.0) * step(d.y, hb.y * 0.5);
                    cr = max(cr, (1.0 - smoothstep(lw * 0.5 - 0.5, lw * 0.5 + 0.5, d.y)) * step(d.x, hb.x * 0.5));
                    e = max(e, cr);
                }
                stroke = max(stroke, e * BA[n]);
                if (outer < 0.0) fill = max(fill, BA[n]);
            }
            if ((amzp_textOn>0.5) && int(amzp_labelMode) > 0) {
                float2 xy = floor(float2(BP[n].x, S.y - BP[n].y) / px + 0.5);
                float nch = labelLen(BI[n], xy);
                if (int(amzp_textStyle) == 1) {
                    float H = max(amzp_textSize, 1.0) * px;
                    float2 lo = BP[n] + float2(-hb.x, hb.y + lw + H * 0.3);
                    float2 l = (P - lo) / H;
                    if (l.y > -0.25 && l.y < 1.15 && l.x > -0.05 && l.x < labelWidth(nch)) {
                        float xa = 0.0;
                        for (int k = 0; k < 12; k++) {
                            if (float(k) >= nch) break;
                            float g = labelChar(float(k), BI[n], xy, BS[n]);
                            float adv = advance(g);
                            if (l.x < xa + adv) {
                                float dd = sdGlyph(g, float2(l.x - xa, l.y));
                                float aa = 0.8 / H;
                                textA = max(textA, (1.0 - smoothstep(0.06 - aa, 0.06 + aa, dd)) * BA[n]);
                                break;
                            }
                            xa += adv;
                        }
                    }
                } else {
                    float u = max(amzp_textSize, 1.0) * px / 5.0;
                    float2 lo = BP[n] + float2(-hb.x, hb.y + lw + u);
                    float2 l = (P - lo) / u;
                    if (l.x >= 0.0 && l.y >= 0.0 && l.y < 5.0 && l.x < nch * 4.0) {
                        float k = floor(l.x / 4.0);
                        float cx = floor(l.x - k * 4.0);
                        float g = labelChar(k, BI[n], xy, BS[n]);
                        if (g >= 0.0 && cx < 3.0) textA = max(textA, bitAt(glyph(g), 4.0 - floor(l.y), cx) * BA[n]);
                    }
                }
            }
        }
        if ((amzp_linkOn>0.5)) {
            float ld = clamp(amzp_linkDist, 0.5, 2.5) * G;
            for (int a = 0; a < 25; a++) {
                if (BA[a] <= 0.001) continue;
                for (int b = 0; b < 25; b++) {
                    if (b <= a) continue;
                    if (BA[b] <= 0.001) continue;
                    float2 ab = BP[b] - BP[a];
                    float L = length(ab);
                    if (L > ld) continue;
                    if (h2(floor(BP[a] / G) * 31.0 + floor(BP[b] / G), 5.0) >= clamp(amzp_linkProb, 0.0, 1.0)) continue;
                    float t;
                    float dd = segD(P, BP[a], BP[b], t);
                    float e = 1.0 - smoothstep(lw * 0.35 - 0.5, lw * 0.35 + 0.5, dd);
                    if ((amzp_dashed>0.5)) e *= step(0.5, fract(t * L / (10.0 * px)));
                    lineA = max(lineA, e * min(BA[a], BA[b]));
                }
            }
        }
        float arrA = 0.0;
        if ((amzp_curveOn>0.5)) {
            float ld = clamp(amzp_linkDist, 0.5, 2.5) * G;
            float cw = max(amzp_lineWidth, 0.5) * px * 0.4;
            float asz = max(amzp_arrowSize, 1.0) * px;
            float dl = max(amzp_curveDash, 0.0) * px;
            float nA = clamp(floor(amzp_arrowCount + 0.5), 0.0, 4.0);
            float bend = clamp(amzp_curveBend, 0.0, 1.0);
            for (int a = 0; a < 25; a++) {
                if (BA[a] <= 0.001) continue;
                for (int b = 0; b < 25; b++) {
                    if (b <= a) continue;
                    if (BA[b] <= 0.001) continue;
                    float2 ga = floor(BP[a] / G), gb = floor(BP[b] / G);
                    float2 A = BP[a], B = BP[b];
                    float2 ab = B - A;
                    float L = length(ab);
                    if (L > ld || L < 1.0) continue;
                    if (h2(ga * 31.0 + gb, 6.0) >= clamp(amzp_curveProb, 0.0, 1.0)) continue;
                    if (h2(ga * 17.0 + gb, 7.0) < 0.5) { A = BP[b]; B = BP[a]; ab = -ab; }
                    float2 nrm = float2(-ab.y, ab.x) / L;
                    float side = h2(gb * 13.0 + ga, 8.0) < 0.5 ? -1.0 : 1.0;
                    float2 C = 0.5 * (A + B) + nrm * side * bend * L;
                    float mg = asz + cw + 2.0;
                    float2 lo = min(min(A, B), C) - mg, hi = max(max(A, B), C) + mg;
                    if (P.x < lo.x || P.y < lo.y || P.x > hi.x || P.y > hi.y) continue;
                    float best = 1e9, sb = 0.0, acc = 0.0;
                    float2 q0 = A;
                    for (int k = 1; k <= 12; k++) {
                        float t = float(k) / 12.0;
                        float2 q1 = mix(mix(A, C, t), mix(C, B, t), t);
                        float tt;
                        float d = segD(P, q0, q1, tt);
                        float sl = length(q1 - q0);
                        if (d < best) { best = d; sb = acc + tt * sl; }
                        acc += sl;
                        q0 = q1;
                    }
                    float e = 1.0 - smoothstep(cw - 0.5, cw + 0.5, best);
                    if (dl > 0.5) e *= step(0.5, fract(sb / (2.0 * dl)));
                    for (int k = 0; k < 4; k++) {
                        if (float(k) >= nA) break;
                        float t = (float(k) + 1.0) / (nA + 1.0);
                        float2 q = mix(mix(A, C, t), mix(C, B, t), t);
                        float2 tg = mix(C - A, B - C, t);
                        tg /= max(length(tg), 1e-4);
                        float2 pn = float2(-tg.y, tg.x);
                        float2 tip = q + tg * asz * 0.5;
                        float tt;
                        float d1 = segD(P, tip, tip - tg * asz + pn * asz * 0.6, tt);
                        float d2 = segD(P, tip, tip - tg * asz - pn * asz * 0.6, tt);
                        e = max(e, 1.0 - smoothstep(cw - 0.5, cw + 0.5, min(d1, d2)));
                    }
                    arrA = max(arrA, e * min(BA[a], BA[b]));
                }
            }
        }
        float4 base = int(amzp_composite) == 1 ? float4(0.0) : orig;
        if ((amzp_boxOn>0.5) && fill > 0.001 && int(amzp_fillMode) > 0) {
            float fo = clamp(amzp_fillOpacity, 0.0, 1.0) * fill;
            float3 u = orig.a > 0.0001 ? orig.rgb / orig.a : float3(0.0);
            float3 f;
            if (int(amzp_fillMode) == 1) f = amzp_boxColor.rgb;
            else if (int(amzp_fillMode) == 2) f = 1.0 - u;
            else if (int(amzp_fillMode) == 3) f = float3(dot(u, float3(0.299, 0.587, 0.114)));
            else f = thermal(dot(u, float3(0.299, 0.587, 0.114)));
            float fa = int(amzp_fillMode) == 1 ? fo : max(orig.a, 0.0);
            float4 fc = float4(f * fa, fa);
            base = int(amzp_fillMode) == 1 ? fc + base * (1.0 - fa) : mix(base, fc, fo);
        }
        float op = clamp(amzp_opacity, 0.0, 1.0);
        float4 o = base;
        o = float4(amzp_lineColor.rgb, 1.0) * lineA * op + o * (1.0 - lineA * op);
        o = float4(amzp_curveColor.rgb, 1.0) * arrA * op + o * (1.0 - arrA * op);
        o = float4(amzp_boxColor.rgb, 1.0) * stroke * op + o * (1.0 - stroke * op);
        o = float4(amzp_textColor.rgb, 1.0) * textA * op + o * (1.0 - textA * op);
        amzOutput = float4(min(o.rgb, float3(o.a)), o.a);
    }
    void amzRender() {
        if ((amzp_safeRender>0.5)) { amzOutput = amzTexture(0, amzScreenNorm()); return; }
        nmMain();
        if (!(amzp_overdrawOn>0.5) && amzPass >= 2) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*64.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

